import{_ as h,o as i,c as t,a2 as a}from"./chunks/framework.B2OIHwwP.js";const s=JSON.parse('{"title":"Phản hồi của artist: kế hoạch và danh sách kiểm (bản tiếng Việt)","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/artist-feedback.vi.md","filePath":"gdd/artist-feedback.vi.md"}'),c={name:"gdd/artist-feedback.vi.md"};function o(l,n,e,g,u,r){return i(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="phan-hoi-cua-artist-ke-hoach-va-danh-sach-kiem-ban-tieng-viet" tabindex="-1">Phản hồi của artist: kế hoạch và danh sách kiểm (bản tiếng Việt) <a class="header-anchor" href="#phan-hoi-cua-artist-ke-hoach-va-danh-sach-kiem-ban-tieng-viet" aria-label="Permalink to &quot;Phản hồi của artist: kế hoạch và danh sách kiểm (bản tiếng Việt)&quot;">​</a></h1><p>Mỗi gạch đầu dòng là một ý của artist. Trạng thái: <code>[ ]</code> chưa xong, <code>[x]</code> đã làm và đã kiểm, <code>[?]</code> cần chủ dự án quyết định. Bản gốc tiếng Anh: <code>artist-feedback.md</code>.</p><h2 id="r-đoi-ten-game-thanh-fishy-find-chu-du-an-đa-quyet" tabindex="-1">R. Đổi tên game thành &quot;Fishy Find&quot; (chủ dự án đã quyết) <a class="header-anchor" href="#r-đoi-ten-game-thanh-fishy-find-chu-du-an-đa-quyet" aria-label="Permalink to &quot;R. Đổi tên game thành &quot;Fishy Find&quot; (chủ dự án đã quyết)&quot;">​</a></h2><ul><li>[x] R1 Logo mới &quot;FISHY FIND&quot;, tạo bằng ChatGPT (chủ dự án cho phép riêng cho logo, thay cho quy tắc &quot;không dùng ChatGPT&quot; trong CLAUDE.md), nền trong suốt (vẽ trên nền một màu rồi xoá màu bằng script có sẵn)</li><li>[x] R2 Tên người chơi nhìn thấy: tiêu đề trang, màn hình tải, tiêu đề tài liệu, trang giới thiệu, các pop-up có chữ &quot;Spot A Fish&quot;</li><li>[x] R3 KHÔNG đổi (sẽ làm hỏng đường dẫn và dữ liệu lưu): tên repo và địa chỉ Pages <code>spot-a-fish</code>, khoá lưu <code>findfish_v1</code>, tên biến trong code. Đổi tên repo là việc của chủ dự án.</li></ul><h2 id="a-logo-game-man-hinh-tai-logo-moi-bao-gom-a1-đen-a3" tabindex="-1">A. Logo game / màn hình tải (logo mới bao gồm A1 đến A3) <a class="header-anchor" href="#a-logo-game-man-hinh-tai-logo-moi-bao-gom-a1-đen-a3" aria-label="Permalink to &quot;A. Logo game / màn hình tải (logo mới bao gồm A1 đến A3)&quot;">​</a></h2><ul><li>[x] A1 Chữ thứ hai (FIND): màu vàng cam thay cho hồng cam</li><li>[x] A2 Bớt các ngôi sao lấp lánh quanh logo (rối quá)</li><li>[x] A3 Con cá trong kính lúp chưa đẹp: vẽ con đẹp hơn trong logo mới</li><li>[?] A4 Bỏ con cá thứ hai dưới thanh tải, thay bằng một icon <code>[?]</code> chọn icon nào (hiện dùng kính lúp)</li><li>[x] A5 Phần fill của thanh tải sáng hơn (không cùng màu với khung), có lớp nền tối hơn dưới khung, chữ nằm trên thanh</li></ul><h2 id="b-icon-level-pause-booster" tabindex="-1">B. Icon: Level, Pause, Booster <a class="header-anchor" href="#b-icon-level-pause-booster" aria-label="Permalink to &quot;B. Icon: Level, Pause, Booster&quot;">​</a></h2><ul><li>[x] B1 Icon quá to, che mất bong bóng của nút: thu nhỏ icon (hoặc bỏ bong bóng nếu không cần)</li><li>[x] B2 Icon rung (vibration) trong Settings bị hỏng: kiểm và sửa</li></ul><h2 id="c-huong-dan-lan-đau-cho-booster-ftue" tabindex="-1">C. Hướng dẫn lần đầu cho Booster (FTUE) <a class="header-anchor" href="#c-huong-dan-lan-đau-cho-booster-ftue" aria-label="Permalink to &quot;C. Hướng dẫn lần đầu cho Booster (FTUE)&quot;">​</a></h2><ul><li>[x] C1 Căn chữ vào giữa khung</li><li>[x] C2 Sửa mũi tên chỉ của bong bóng thoại</li></ul><h2 id="d-man-hinh-tinh-nang-moi" tabindex="-1">D. Màn hình tính năng mới <a class="header-anchor" href="#d-man-hinh-tinh-nang-moi" aria-label="Permalink to &quot;D. Màn hình tính năng mới&quot;">​</a></h2><ul><li>[x] D1 Chưa có hiệu ứng cho chữ &quot;NEW FEATURE&quot; và tên tính năng</li><li>[x] D2 Bỏ khung chữ (chỉ để chữ)</li><li>[x] D3 Có nút &quot;Continue&quot; thay cho dòng &quot;Tap to continue&quot;</li></ul><h2 id="e-nen-theme-moi-10-level" tabindex="-1">E. Nền theme mỗi 10 level <a class="header-anchor" href="#e-nen-theme-moi-10-level" aria-label="Permalink to &quot;E. Nền theme mỗi 10 level&quot;">​</a></h2><ul><li>[x] E1 Có hai theme trông giống nhau: mỗi theme trong 6 theme phải có màu khác hẳn</li><li>[x] E2 Khi đổi theme phải thấy rõ sự thay đổi (để người chơi cảm nhận được)</li></ul><h2 id="f-level-hard-super-hard" tabindex="-1">F. Level Hard / Super Hard <a class="header-anchor" href="#f-level-hard-super-hard" aria-label="Permalink to &quot;F. Level Hard / Super Hard&quot;">​</a></h2><ul><li>[x] F1 &quot;LEVEL 10&quot; và &quot;LEVEL 20&quot;: các chữ số đè lên nhau</li><li>[x] F2 Số level quá nhạt: chữ trắng có viền, huy hiệu tròn màu tím (Hard) / đỏ (Super Hard)</li></ul><h2 id="g-kieu-chu-moi-pop-up-va-tieu-đe" tabindex="-1">G. Kiểu chữ (mọi pop-up và tiêu đề) <a class="header-anchor" href="#g-kieu-chu-moi-pop-up-va-tieu-đe" aria-label="Permalink to &quot;G. Kiểu chữ (mọi pop-up và tiêu đề)&quot;">​</a></h2><ul><li>[x] G1 Màu đang nhạt kiểu pastel viền trắng: làm sống động, thêm viền mảnh màu tối (nâu đen hoặc xanh đen)</li><li>[x] G2 Chữ trắng có viền tối dày</li><li>[x] G3 Một quy tắc chung cho bóng đen của chữ (pop-up Settings đang khác các chỗ còn lại)</li><li>[x] G4 Không có hiệu ứng sóng, gợn trên chữ</li></ul><h2 id="h-be-đich-target-va-o-backup" tabindex="-1">H. Bể đích (target) và ô Backup <a class="header-anchor" href="#h-be-đich-target-va-o-backup" aria-label="Permalink to &quot;H. Bể đích (target) và ô Backup&quot;">​</a></h2><ul><li>[x] H1 Bể đích: bỏ cây cỏ hai bên</li><li>[x] H2 Backup: bỏ tia sáng chiếu xuống</li><li>[x] H3 Cả hai: dựng 3D hơn, theo phong cách bể lớn bên dưới</li><li>[x] H4 Hình nền phía sau trông phẳng / 2D</li></ul><h2 id="i-ket-thuc-đot-nay" tabindex="-1">I. Kết thúc đợt này <a class="header-anchor" href="#i-ket-thuc-đot-nay" aria-label="Permalink to &quot;I. Kết thúc đợt này&quot;">​</a></h2><ul><li>[ ] I1 Kiểm từng mục trên màn hình cỡ điện thoại và màn hình rộng</li><li>[ ] I2 Ghi changelog và phát hành</li></ul><hr><h2 id="cac-yeu-cau-bo-sung-phat-sinh-sau-đo-khong-co-trong-danh-sach-cua-artist" tabindex="-1">Các yêu cầu bổ sung phát sinh sau đó (không có trong danh sách của artist) <a class="header-anchor" href="#cac-yeu-cau-bo-sung-phat-sinh-sau-đo-khong-co-trong-danh-sach-cua-artist" aria-label="Permalink to &quot;Các yêu cầu bổ sung phát sinh sau đó (không có trong danh sách của artist)&quot;">​</a></h2><p>Phần này là những việc chủ dự án nhắn thêm trong lúc làm bể đích và Backup. Chưa có trong bản gốc tiếng Anh.</p><h3 id="be-đich-target" tabindex="-1">Bể đích (target) <a class="header-anchor" href="#be-đich-target" aria-label="Permalink to &quot;Bể đích (target)&quot;">​</a></h3><ul><li>[x] Bể là hộp kính chữ nhật thật có độ sâu (vách sau, hai vách bên, nền cát, mặt nước), thành kính mỏng như bể lớn</li><li>[x] Nắp và tấm hiển thị cá là <strong>một</strong>: nắp xoay mở lên trên bản lề ở thành sau, dựng thẳng 90°, mặt trong nắp là biển LED hiện cá cần tìm và số lượng; đóng thì chỉ thấy mặt nắp</li><li>[x] Bản lề chỉ một chiếc ở giữa thành sau, đứng yên; có gờ miệng bể nối nắp với bể</li><li>[x] Khi hoàn thành bể: nắp đóng trước, rồi bể mới xoáy; bể mới có nắp đóng rồi mở ra; restart level cũng có hoạt cảnh mở nắp</li><li>[x] Biển LED: nền kính tối, lưới điểm LED, cá phát sáng, chữ số sáng; bật lên có nhấp nháy, đổi số thì chớp một lần</li><li>[ ] Biển LED có lúc một bên mờ một bên sáng (chủ dự án thấy): chưa tái hiện được, đã thêm cơ chế tự vẽ lại để không kẹt ở trạng thái tối</li><li>[x] Mặt nước sóng sánh, giọt nước bắn nhỏ và cùng màu nước</li><li>[x] Cá bay (lên bể, xuống Backup, xuống bể lớn) được vẽ trên mọi lớp, trừ bể lớn</li><li>[x] Cá trong bể to vừa phải, không lòi ra khỏi thành</li><li>[x] Cá chạm nước thì chìm xuống theo quán tính rồi ngẩng lên (ở bể đích đã đo; ở bể lớn và màn thắng chưa xem bằng mắt)</li></ul><h3 id="backup-o-giam" tabindex="-1">Backup (ô giam) <a class="header-anchor" href="#backup-o-giam" aria-label="Permalink to &quot;Backup (ô giam)&quot;">​</a></h3><ul><li>[x] Hướng thiết kế: &quot;buồng giam&quot;: khung thép, song sắt, nước đục hơn, đối lập với bể đích sáng</li><li>[x] Mỗi ô là một buồng có song chắn trước kính; cá nằm sau song</li><li>[x] Mặt nước có sóng và nhấp nhô khi có cá rơi vào; cảnh báo đỏ khi gần đầy</li><li>[x] Con mực (sau này là bạch tuộc) chiếm 3 ô: nằm ngang trải qua ba ô, vẽ đè lên song của chính nó để không bị song cắt</li><li>[x] Thành trên mỏng và dẹt hơn</li><li>[x] Khung là một vòng liền, các cạnh cắt xéo 45° tại góc; đã bỏ đinh tán</li><li>[ ] Khung vẫn bị chủ dự án chê thô; đang chuyển sang nhờ ChatGPT vẽ bộ phận khung (góc, thanh ngang, thanh dọc)</li><li>[ ] Cá trong ô bị cắt bởi khung: đã thu nhỏ cá cho vừa chiều cao ô, cần chủ dự án xem lại</li></ul><h3 id="am-thanh" tabindex="-1">Âm thanh <a class="header-anchor" href="#am-thanh" aria-label="Permalink to &quot;Âm thanh&quot;">​</a></h3><ul><li>[x] Đã gắn 17 file âm thanh mới; âm combo 1 đến 4 rồi giữ nguyên âm 4 cho đến khi gãy combo</li><li>[x] <code>sfx_win_swirl</code> dời trễ cho khớp lúc cá bắt đầu xoắn; <code>sfx_win_bubble_pop</code> cho bóng nổ cuối màn thắng</li><li>[x] Âm tổng thể giảm, BGM giảm, combo to lên</li><li>[ ] Chưa nghe thử trong game: toàn bộ phần âm thanh mới gắn theo code</li></ul><h3 id="khac" tabindex="-1">Khác <a class="header-anchor" href="#khac" aria-label="Permalink to &quot;Khác&quot;">​</a></h3><ul><li>[x] Đổi tên hiển thị thành Fishy Find; hai gạch nút Pause không còn biến mất khi kéo camera; căn giữa số level và hai gạch</li><li>[x] Màn rong rêu: ít cây hơn, ngắn hơn, không lòi ra ngoài kính</li><li>[x] Icon booster to hơn một chút và căn giữa</li><li>[x] Kính lúp trên thanh tải làm chữ &quot;Finding fish&quot; phồng lên như kính lồi; kính căn giữa thanh</li></ul>',33)])])}const d=h(c,[["render",o]]);export{s as __pageData,d as default};
